/* Middle Eastern and African recipes: famous dishes and everyday home cooking. Same fields as recipes.js. */
RECIPES.push(
 {id:"hummus",title:"Creamy Hummus with Warm Pita",cuisine:"Lebanese",diet:["vegan","vegetarian","halal"],serves:6,cost:0.75,meal:["snack","lunch"],tags:["dip","beans"],
  desc:"Silky-smooth chickpea dip blended with tahini, lemon, and garlic, swirled into a bowl and topped with olive oil, paprika, and whole chickpeas. Eaten with warm pita at nearly every Lebanese meal. The trick to restaurant-smooth hummus is simmering canned chickpeas first.",
  pantry:["chickpeas","tahini","lemon","garlic","olive oil","cumin","paprika","pita"],
  ingredients:["2 cans (400 g / 15 oz each) chickpeas, drained and rinsed","½ tsp baking soda","⅓ cup (80 g) tahini, stirred well","Juice of 1½ lemons (about 4 tbsp)","1 garlic clove","¾ tsp salt","½ tsp ground cumin","4–6 tbsp ice water","Olive oil, paprika, and parsley, to serve","Warm pita, to serve"],
  steps:[
   {name:"Simmer the chickpeas",desc:"Put the chickpeas and baking soda in a pot, cover with water, and simmer 15 min until very soft and the skins float. Drain and rinse. (Skins rub off easily now; removing them makes it even smoother.) Save a spoonful of whole chickpeas for the top.",min:17},
   {name:"Blend the tahini",desc:"Blend the tahini, lemon juice, garlic, salt, and cumin 1 min. It will turn thick and pale.",min:2,timer:false},
   {name:"Blend the hummus",desc:"Add the warm chickpeas and blend 3–4 min, scraping down the sides, while adding ice water 1 tbsp at a time until very smooth and fluffy. Taste and add salt or lemon.",min:5,timer:false},
   {name:"Serve",desc:"Swirl into a shallow bowl with the back of a spoon. Fill the swirl with olive oil and top with paprika, parsley, and the whole chickpeas. Serve with warm pita.",min:3,timer:false}]},
 {id:"tabbouleh",title:"Tabbouleh",cuisine:"Lebanese",diet:["vegan","vegetarian","halal"],serves:4,cost:1.50,meal:["side","lunch"],tags:["salad"],
  desc:"Lebanon's famous herb salad: mostly finely chopped fresh parsley and mint, with a little bulgur wheat, tomato, and onion, dressed with lots of lemon and olive oil. Bright green, zingy, and fresh; not a grain salad.",
  pantry:["parsley","mint","bulgur","tomatoes","green onion","lemon","olive oil"],
  ingredients:["¼ cup (40 g) fine bulgur","3 large bunches flat-leaf parsley","1 small bunch mint","3 tomatoes, finely diced","3 green onions, finely sliced","Juice of 2 lemons","⅓ cup (80 ml) extra-virgin olive oil","¾ tsp salt","Pinch of allspice or cinnamon (optional)","Romaine leaves, to scoop"],
  steps:[
   {name:"Soak the bulgur",desc:"Cover the bulgur with the lemon juice and 2 tbsp water and let it soften 15 min.",min:15},
   {name:"Chop the herbs",desc:"Wash and dry the parsley and mint very well (wet herbs turn mushy). Pick off the thick stems, bunch the leaves tightly, and slice as finely as you can with a sharp knife. This takes time; it's the heart of the dish.",min:15,timer:false},
   {name:"Mix",desc:"Put the tomatoes, green onions, herbs, and soaked bulgur (with its lemon) in a bowl. Add the olive oil, salt, and allspice and toss well.",min:3,timer:false},
   {name:"Serve",desc:"Taste: it should be quite lemony. Add more lemon or salt as needed. Serve right away with romaine leaves to scoop it.",min:1,timer:false}]},
 {id:"falafel",title:"Baked or Fried Falafel",cuisine:"Lebanese",diet:["vegan","vegetarian","halal"],serves:4,cost:1.00,meal:["lunch","dinner"],tags:["fried","beans","wrap"],
  desc:"Crispy, herb-green balls of ground soaked chickpeas, onion, garlic, and cumin, crunchy outside and fluffy inside. Stuffed into pita with tahini sauce, pickles, and salad, it's one of the most popular street foods in the Middle East.",
  pantry:["dried chickpeas","parsley","cilantro","onion","garlic","cumin","coriander","baking powder","tahini","pita"],
  ingredients:["1 cup (200 g) dried chickpeas (soaked overnight in step 1; canned won't hold together)","1 small onion, chopped","4 garlic cloves","1 large handful each parsley and cilantro","1½ tsp ground cumin","1 tsp ground coriander","1 tsp salt","½ tsp baking powder","2 tbsp flour or chickpea flour","Oil, for frying (or 3 tbsp for baking)","Tahini sauce: ¼ cup tahini, 3 tbsp lemon juice, 1 small garlic clove grated, ¼ tsp salt, 3–5 tbsp water","Pita, tomato, cucumber, pickles, to serve"],
  steps:[
   {name:"Soak the chickpeas (the night before)",desc:"Put the dried chickpeas in a big bowl and cover with at least 5 cm (2 in) of cold water; they double in size. Leave them on the counter overnight, 8–24 hours. Canned chickpeas won't work here; they're too soft to hold together.",min:480,timer:false,prep:true,overnight:true},
   {name:"Grind the mixture",desc:"Drain the soaked chickpeas well. Pulse them in a food processor with the onion, garlic, herbs, spices, and salt until it looks like coarse sand and holds together when squeezed. Don't make a paste. Stir in the baking powder and flour and chill 15 min.",min:20},
   {name:"Make the tahini sauce",desc:"Whisk the tahini, lemon, garlic, and salt. It will seize up; keep whisking in water until smooth and pourable.",min:3,timer:false},
   {name:"Shape",desc:"Squeeze 2-tbsp portions into balls or small patties.",min:8,timer:false},
   {name:"Cook",desc:"Fry in 5 cm (2 in) of oil at 350°F (175°C) (no thermometer? a cube of bread should turn golden in about 60 seconds) until deep brown, 3–4 min. Or to bake: brush with oil and bake on a sheet pan at 400°F (200°C), 25 min, flipping halfway.",min:15},
   {name:"Serve",desc:"Stuff into pita with tomato, cucumber, pickles, and plenty of tahini sauce.",min:3,timer:false}]},
 {id:"menemen",title:"Menemen (Turkish Scrambled Eggs)",cuisine:"Turkish",diet:["vegetarian","halal"],serves:2,cost:1.25,meal:["breakfast"],tags:["eggs","onepot"],
  desc:"A favorite Turkish breakfast: soft scrambled eggs cooked into a juicy sauce of sautéed peppers and ripe tomatoes, eaten straight from the pan with crusty bread. Simpler and softer than shakshuka.",
  pantry:["eggs","tomatoes","green pepper","butter","olive oil","chili flakes","bread"],
  ingredients:["1 tbsp olive oil","1 tbsp butter","2 long green peppers or 1 green bell pepper, chopped","3 ripe tomatoes, grated or finely chopped","½ tsp salt","4 eggs","½ tsp Aleppo pepper or a pinch of chili flakes","Crusty bread, to serve"],
  steps:[
   {name:"Soften the peppers",desc:"Heat the oil and butter in a skillet over medium heat. Cook the peppers 5 min until soft.",min:5},
   {name:"Cook the tomatoes",desc:"Add the tomatoes and salt and simmer until thick and saucy, 6–8 min.",min:7},
   {name:"Add the eggs",desc:"Crack in the eggs and stir gently a few times, just until softly set but still glossy, 2 min. Don't overcook; menemen should be soft and juicy.",min:2,timer:false},
   {name:"Serve",desc:"Sprinkle with Aleppo pepper and serve in the pan with bread for scooping.",min:1,timer:false}]},
 {id:"mercimek-corbasi",title:"Mercimek Çorbası (Red Lentil Soup)",cuisine:"Turkish",diet:["vegan","vegetarian","halal","glutenfree"],serves:6,cost:0.50,meal:["dinner","lunch"],tags:["soup","beans"],
  desc:"Turkey's everyday soup, served in homes and restaurants alike: red lentils, onion, carrot, and potato simmered and blended into a silky golden soup, finished with a sizzle of paprika butter (or oil) and a squeeze of lemon.",
  pantry:["red lentils","onion","carrots","potatoes","tomato paste","cumin","paprika","broth","lemon"],
  ingredients:["3 tbsp olive oil","1 onion, diced","1 carrot, diced","1 small potato, diced","1 tbsp tomato paste","1 tsp ground cumin","1½ cups (300 g) red lentils, rinsed","8 cups (2 L) water or vegetable broth","1½ tsp salt","Topping: 2 tbsp olive oil, 1 tsp paprika, ½ tsp dried mint","Lemon wedges, to serve"],
  steps:[
   {name:"Soften the vegetables",desc:"Heat the oil in a pot over medium heat. Cook the onion, carrot, and potato 6 min. Stir in the tomato paste and cumin for 1 min.",min:7},
   {name:"Simmer",desc:"Add the lentils, water, and salt. Bring to a boil, skim off any foam, and simmer until the lentils are completely soft and falling apart, 25 min.",min:25},
   {name:"Blend",desc:"Blend until silky smooth with a stick blender (or carefully in batches in a blender). Add water if it's too thick. Taste for salt.",min:3,timer:false},
   {name:"Sizzle and serve",desc:"Heat the topping oil in a small pan, add the paprika and mint, and swirl 20 seconds until it sizzles red. Drizzle over each bowl. Serve with lemon to squeeze in.",min:2,timer:false}]},
 {id:"kofte",title:"Izgara Köfte (Turkish Meatballs)",cuisine:"Turkish",diet:["halal"],serves:4,cost:2.50,meal:["dinner"],tags:["grill"],
  desc:"Juicy, finger-shaped beef and lamb meatballs flavored with onion, garlic, cumin, and parsley, grilled or pan-seared until charred. A Turkish street food staple, served with rice or bread, grilled peppers, tomato, and sumac onions.",
  pantry:["ground beef","onion","garlic","breadcrumbs","parsley","cumin","paprika","red onion","sumac"],
  ingredients:["680 g (1½ lb) ground beef, or beef and lamb (halal-certified to keep it halal)","1 small onion, finely grated and squeezed dry","2 garlic cloves, grated","⅓ cup (20 g) breadcrumbs","1 handful parsley, finely chopped","1½ tsp ground cumin","1 tsp paprika","1 tsp salt","½ tsp pepper","Sumac onions: 1 red onion thinly sliced, 1 tsp sumac, 1 handful parsley, pinch of salt","Rice or flatbread, grilled peppers, and tomatoes, to serve"],
  steps:[
   {name:"Mix and knead",desc:"Mix the meat with the onion, garlic, breadcrumbs, parsley, spices, salt, and pepper, kneading 3 min until sticky. Chill 20 min so it firms up.",min:23},
   {name:"Make the sumac onions",desc:"Toss the red onion with the sumac, parsley, and salt.",min:3,timer:false},
   {name:"Shape",desc:"With wet hands, shape into 16 small logs, about 8 cm (3 in) long, and flatten slightly.",min:6,timer:false},
   {name:"Grill",desc:"Cook on a very hot grill pan or skillet, 3–4 min per side, until charred and no longer pink in the middle (160°F / 71°C).",min:8},
   {name:"Serve",desc:"Serve with rice or bread, the sumac onions, and grilled peppers and tomatoes.",min:2,timer:false}]},
 {id:"lahmacun",title:"Lahmacun (Turkish Flatbread Pizza)",cuisine:"Turkish",diet:["halal"],serves:4,cost:1.75,meal:["lunch","dinner"],tags:["bread","pizza","oven"],
  desc:"Very thin, crispy flatbreads spread with a spiced mixture of ground meat, tomato, pepper, onion, and herbs, baked hot and fast. Squeeze lemon on top, add parsley and onion, roll it up, and eat it like a wrap. A favorite Turkish street food.",
  pantry:["pizza dough","ground beef","tomato","bell pepper","onion","garlic","tomato paste","parsley","paprika","cumin","lemon"],
  ingredients:["450 g (1 lb) store-bought pizza dough, or 4 large flour tortillas for a quick version","225 g (8 oz) ground beef or lamb (halal-certified to keep it halal)","1 tomato, very finely chopped","½ red bell pepper, very finely chopped","½ onion, very finely chopped","2 garlic cloves, minced","2 tbsp tomato paste","1 handful parsley, finely chopped","1 tsp paprika or Aleppo pepper","½ tsp ground cumin","¾ tsp salt","Lemon wedges, parsley, and sliced onion, to serve"],
  steps:[
   {name:"Make the topping",desc:"Heat the oven as hot as it goes, 500°F (260°C), with a sheet pan inside. Mix the meat, tomato, pepper, onion, garlic, tomato paste, parsley, spices, and salt into a soft paste.",min:8,timer:false},
   {name:"Roll the dough",desc:"Divide the dough into 4 and roll each piece paper-thin into an oval about 30 cm (12 in) long.",min:8,timer:false},
   {name:"Spread",desc:"Spread a quarter of the topping in a very thin layer all the way to the edges.",min:4,timer:false},
   {name:"Bake",desc:"Slide 1 or 2 onto the hot pan (on parchment) and bake until the edges are crisp and the meat is cooked, 7–9 min (tortillas: 5–6 min).",min:16},
   {name:"Serve",desc:"Top with parsley and onion, squeeze lemon over, and roll up to eat.",min:2,timer:false}]},
 {id:"ghormeh-sabzi",title:"Ghormeh Sabzi (Persian Herb Stew)",cuisine:"Persian",diet:["halal","glutenfree"],serves:6,cost:3.00,meal:["dinner"],tags:["stew","beans"],
  desc:"Iran's most beloved stew: beef and kidney beans slow-cooked with a huge amount of sautéed fresh herbs (parsley, cilantro, chives, fenugreek) and tangy dried limes. Dark green, sour, and deeply savory; served over saffron rice.",
  pantry:["beef stew meat","parsley","cilantro","green onion","fenugreek","kidney beans","dried limes","onion","turmeric"],
  ingredients:["680 g (1½ lb) beef or lamb stew meat, in 3 cm (1 in) cubes (halal-certified to keep it halal)","4 tbsp oil, divided","1 onion, diced","1 tsp ground turmeric","5 cups (1.2 L) water","4 dried limes (limoo amani), pierced with a fork (or juice of 2 limes, added at the end)","3 large bunches parsley, 1 bunch cilantro, 1 bunch green onions or chives, all finely chopped (or 2 cups dried ghormeh sabzi herb mix, soaked)","2 tbsp dried fenugreek leaves","1 can (400 g / 15 oz) red kidney beans, drained","1½ tsp salt","½ tsp pepper","Persian rice (chelow), to serve"],
  steps:[
   {name:"Brown the meat",desc:"Heat 2 tbsp oil in a heavy pot over medium heat. Cook the onion until golden, 8 min. Add the meat and turmeric and brown 6 min.",min:14},
   {name:"Simmer the meat",desc:"Add the water and dried limes, bring to a boil, cover, and simmer 1 hour.",min:60},
   {name:"Fry the herbs",desc:"Meanwhile, heat 2 tbsp oil in a large skillet over medium heat. Fry the chopped herbs, stirring often, until they shrink, turn dark green, and smell earthy, about 15 min. Stir in the fenugreek for 1 min.",min:16},
   {name:"Simmer together",desc:"Add the herbs, beans, salt, and pepper to the pot. Cover and simmer 1 hour more, until the meat is tender and a little oil rises to the top. Squeeze the limes against the pot with a spoon for more sourness.",min:60},
   {name:"Serve",desc:"Taste for salt and sourness. Serve over rice.",min:2,timer:false}]},
 {id:"chelow-tahdig",title:"Persian Rice with Tahdig",cuisine:"Persian",diet:["vegetarian","halal","glutenfree"],serves:6,cost:0.75,meal:["side","dinner"],tags:["rice"],
  desc:"Fluffy, long-grain Persian steamed rice with a golden, crunchy crust on the bottom called tahdig, the most fought-over part of any Persian meal. Topped with saffron rice and served with stews and kebabs.",
  pantry:["basmati rice","saffron","yogurt","butter","oil"],
  ingredients:["2½ cups (500 g) basmati rice","2 tbsp salt, for soaking and boiling","Pinch of saffron, ground and steeped in 3 tbsp hot water (or ¼ tsp turmeric)","3 tbsp plain yogurt","4 tbsp oil","2 tbsp butter, melted"],
  steps:[
   {name:"Rinse and soak",desc:"Rinse the rice in cool water, swishing, until the water runs nearly clear. Soak in water with 1 tbsp salt for 30 min (up to 2 hours).",min:30,prep:true},
   {name:"Parboil",desc:"Bring a large pot of water and 1 tbsp salt to a boil. Add the drained rice and boil 6–7 min, until the grains are soft outside but still firm in the middle. Drain and rinse with lukewarm water.",min:8},
   {name:"Build the tahdig",desc:"Mix 1 cup of the rice with the yogurt, half the saffron water, and 2 tbsp oil. Heat 2 tbsp oil in a nonstick pot over medium heat and press the yogurt rice firmly across the bottom. Pile the rest of the rice on top in a mound, poke 5 holes in it with a spoon handle, and drizzle with the melted butter.",min:6,timer:false},
   {name:"Steam",desc:"Cover the lid with a clean towel (tie the corners up so it can't catch fire) and press it on tightly. Cook on medium 10 min until you hear sizzling, then on low 40 min.",min:50},
   {name:"Flip and serve",desc:"Mix a cup of the top rice with the remaining saffron water for yellow rice. Dip the bottom of the pot in cold water 1 min to loosen the crust, then flip onto a platter, or break the tahdig into pieces and serve on the side.",min:4,timer:false}]},
 {id:"joojeh-kabab",title:"Joojeh Kabab (Saffron Chicken Kebabs)",cuisine:"Persian",diet:["halal","glutenfree"],serves:4,cost:2.75,meal:["dinner"],tags:["grill"],
  desc:"Persian chicken kebabs marinated in saffron, lemon, yogurt, and onion until tender and golden, then grilled with tomatoes. Served on fluffy rice with a pat of butter and a sprinkle of sumac.",
  pantry:["chicken","saffron","lemon","yogurt","onion","butter","tomatoes","sumac","rice"],
  ingredients:["900 g (2 lb) boneless chicken thighs or breasts, in 4 cm (1½ in) pieces (halal-certified to keep it halal)","1 onion, grated","½ cup (120 g) plain yogurt","Juice of 2 lemons","Large pinch of saffron, ground and steeped in 3 tbsp hot water","3 tbsp oil","1½ tsp salt","½ tsp pepper","2 tbsp butter, melted","6 small tomatoes","Sumac and Persian rice, to serve","Metal or soaked wooden skewers"],
  steps:[
   {name:"Marinate",desc:"Mix the onion, yogurt, lemon juice, saffron water, oil, salt, and pepper. Toss with the chicken and marinate at least 4 hours (overnight is best).",min:240,prep:true},
   {name:"Thread",desc:"Thread the chicken onto skewers, pressed together. Put the tomatoes on separate skewers.",min:8,timer:false},
   {name:"Grill",desc:"Grill over medium-high heat or under the broiler, turning every 3 min and brushing with melted butter, until charred in spots and no pink remains inside (165°F / 74°C), 12–15 min. Grill the tomatoes until blistered.",min:14},
   {name:"Serve",desc:"Serve on rice with the tomatoes, a sprinkle of sumac, and a squeeze of lemon.",min:2,timer:false}]},
 {id:"ash-reshteh",title:"Ash Reshteh (Persian Noodle and Bean Soup)",cuisine:"Persian",diet:["vegetarian","halal"],serves:8,cost:1.50,meal:["dinner"],tags:["soup","noodles","beans","onepot"],
  desc:"A thick, hearty Persian soup of beans, lentils, lots of herbs and greens, and noodles, topped with fried mint oil, crispy onions, and tangy whey (kashk). Made in big pots for Persian New Year and cold winter nights.",
  pantry:["kidney beans","chickpeas","lentils","noodles","spinach","parsley","cilantro","onion","turmeric","dried mint","kashk"],
  ingredients:["4 tbsp oil, divided","3 onions, thinly sliced, divided","4 garlic cloves, minced","1 tsp ground turmeric","½ cup (100 g) green or brown lentils","10 cups (2.4 L) water or vegetable broth","1 can each (400 g / 15 oz) kidney beans and chickpeas, drained","4 cups chopped herbs and greens: parsley, cilantro, dill, green onions, spinach","170 g (6 oz) reshteh noodles or linguine, broken in half","2 tsp salt","Topping: 2 tsp dried mint fried in 2 tbsp oil; ½ cup kashk or sour cream thinned with water"],
  steps:[
   {name:"Fry the onions",desc:"Heat 3 tbsp oil in a large pot over medium heat. Fry the onions until deep golden, 15 min. Take out a third for topping. Add the garlic and turmeric to the pot for 1 min.",min:16},
   {name:"Simmer the lentils",desc:"Add the lentils and water, bring to a boil, and simmer 25 min.",min:25},
   {name:"Add beans and herbs",desc:"Add the beans, chickpeas, herbs and greens, and salt. Simmer 20 min, stirring now and then.",min:20},
   {name:"Add the noodles",desc:"Add the noodles and simmer, stirring often so they don't stick, until tender and the soup is thick, 12 min.",min:12},
   {name:"Top and serve",desc:"Fry the dried mint in 2 tbsp oil for 20 seconds. Ladle the soup into bowls and top with swirls of kashk or sour cream, the crispy onions, and mint oil.",min:3,timer:false}]},
 {id:"thieboudienne",title:"Thieboudienne (Senegalese Fish and Rice)",cuisine:"Senegalese",diet:["halal","glutenfree"],seafood:true,serves:6,cost:3.00,meal:["dinner"],tags:["rice","onepot"],
  desc:"Senegal's national dish, shared from one big platter: fish stuffed with a parsley-garlic-chile paste and cooked in a rich tomato sauce with cabbage, carrot, cassava, and eggplant, then broken rice is cooked in that red broth. The crispy rice at the bottom of the pot (xoon) is a treat.",
  pantry:["white fish","parsley","garlic","chile","tomato paste","onion","cabbage","carrots","eggplant","cassava","broken rice","fish sauce"],
  ingredients:["900 g (2 lb) firm white fish steaks (grouper, snapper, or tilapia)","Rof (stuffing): 1 bunch parsley, 4 garlic cloves, 1 hot chile, 1 tsp salt, ½ tsp pepper, blended","⅓ cup (80 ml) oil","1 onion, diced","⅓ cup (90 g) tomato paste","8 cups (2 L) water","1 tbsp fish sauce (instead of fermented fish)","2 tsp salt","½ head cabbage, in 2 wedges","2 carrots, halved","1 small eggplant, halved","300 g (10 oz) cassava or sweet potato, in chunks","3 cups (600 g) broken rice (or jasmine rice, pulsed a few times)","Lime wedges, to serve"],
  steps:[
   {name:"Stuff the fish",desc:"Cut 2 deep slits in each fish steak and push the rof paste into them. Rub any extra on the outside.",min:8,timer:false},
   {name:"Brown the fish and make the sauce",desc:"Heat the oil in a large wide pot over medium-high heat. Brown the fish 2 min per side and set aside. Cook the onion 5 min, then stir in the tomato paste and cook 5 min until dark red.",min:14},
   {name:"Cook the vegetables",desc:"Add the water, fish sauce, salt, and all the vegetables. Simmer 25 min. Add the fish back for the last 10 min, until it flakes easily. Lift out the fish and vegetables onto a platter and cover to keep warm.",min:25},
   {name:"Cook the rice in the broth",desc:"Rinse the rice. Measure the broth left in the pot: you want about 4½ cups (scoop out extra to serve on the side). Add the rice, cover tightly, and cook on low 25 min until tender, letting a crust form on the bottom.",min:25},
   {name:"Serve",desc:"Spread the rice on a big platter and arrange the fish and vegetables on top. Scrape up the crispy bottom rice and serve it alongside, with lime.",min:4,timer:false}]},
 {id:"poulet-yassa",title:"Poulet Yassa (Lemon-Onion Chicken)",cuisine:"Senegalese",diet:["halal"],serves:6,cost:2.00,meal:["dinner"],tags:["stew"],
  desc:"A beloved Senegalese dish: chicken marinated in lots of lemon, mustard, and onions, browned, then simmered in a tangy, sweet, slow-cooked onion sauce with olives and chile. Served over white rice.",
  pantry:["chicken","onions","lemons","mustard","garlic","chile","olives","bouillon","rice"],
  ingredients:["1.4 kg (3 lb) bone-in chicken pieces (halal-certified to keep it halal)","5 large onions, thinly sliced","Juice of 4 lemons","3 tbsp Dijon mustard","4 garlic cloves, minced","1 habanero or Scotch bonnet, whole (or minced for heat)","1½ tsp salt","1 tsp pepper","1 bouillon cube, crumbled","4 tbsp oil","1 cup (240 ml) water","½ cup green olives","Cooked white rice, to serve"],
  steps:[
   {name:"Marinate",desc:"Mix the onions, lemon juice, mustard, garlic, salt, pepper, and bouillon. Add the chicken and marinate at least 2 hours (overnight is best).",min:120,prep:true},
   {name:"Brown the chicken",desc:"Lift the chicken out of the onions (keep the marinade). Heat the oil in a heavy pot over medium-high heat and brown the chicken 4 min per side. Set aside.",min:10},
   {name:"Cook the onions",desc:"Lift the onions out of the marinade and add them to the pot. Cook over medium heat, stirring, until soft and golden, about 15 min.",min:15},
   {name:"Simmer",desc:"Add the chicken, the leftover marinade, water, olives, and whole chile. Cover and simmer 30 min until the chicken is tender. Remove the chile before serving with rice.",min:30}]},
 {id:"accara",title:"Accara (Black-Eyed Pea Fritters)",cuisine:"Senegalese",diet:["vegan","vegetarian","halal","glutenfree"],serves:6,cost:0.75,meal:["snack","breakfast"],tags:["fried","beans"],
  desc:"Crispy, airy fritters of blended black-eyed peas, onion, and chile, sold on street corners across Senegal and West Africa (called akara in Nigeria). Served with a spicy tomato-onion sauce or tucked into bread.",
  pantry:["black-eyed peas","onion","chile","garlic","salt","oil","tomato"],
  ingredients:["2 cups (340 g) dried black-eyed peas (soaked in step 1)","1 small onion, chopped","1 hot chile (Scotch bonnet or jalapeño)","1 garlic clove","1 tsp salt","¼ cup (60 ml) water","Oil, for frying","Quick sauce: 1 onion and 2 tomatoes, chopped, cooked in 2 tbsp oil with ½ tsp salt and a pinch of chili until soft"],
  steps:[
   {name:"Soak the peas",desc:"Cover the dried black-eyed peas with plenty of cold water and soak at least 4 hours (overnight is fine). They soften enough to rub off the skins and blend smooth.",min:240,prep:true},
   {name:"Skin the peas",desc:"Rub the soaked peas between your hands under water so the skins come off and float; pour them off. Repeat until most are skinned (it makes lighter fritters). Drain.",min:20,timer:false},
   {name:"Blend",desc:"Blend the peas with the onion, chile, garlic, salt, and water into a thick, smooth paste. Beat it with a spoon 3 min to whip in air; it should get fluffy.",min:6,timer:false},
   {name:"Fry",desc:"Heat 5 cm (2 in) oil to 350°F (175°C). No thermometer? A drop of batter should sizzle and rise to the top right away. Drop in spoonfuls of batter and fry, turning, until golden brown all over, 3–4 min. Drain on paper towels.",min:18,timer:false},
   {name:"Serve",desc:"Serve hot with the tomato-onion sauce.",min:2,timer:false}]},
 {id:"thiakry",title:"Thiakry (Sweet Millet Couscous Pudding)",cuisine:"Senegalese",diet:["vegetarian","halal"],serves:6,cost:0.75,meal:["dessert","breakfast"],tags:["sweets"],
  desc:"A cool, creamy Senegalese dessert of tiny millet (or couscous) grains folded into sweetened yogurt with vanilla and nutmeg, often with raisins. Eaten at celebrations, especially at the end of Ramadan.",
  pantry:["couscous","yogurt","condensed milk","vanilla","nutmeg","raisins"],
  ingredients:["1 cup (180 g) millet couscous (arraw), or regular couscous","1 cup (240 ml) boiling water","1 tbsp butter","2 cups (480 g) plain yogurt","½ cup (120 ml) sweetened condensed milk, or to taste","1 tsp vanilla extract","¼ tsp ground nutmeg","¼ cup raisins (optional)"],
  steps:[
   {name:"Steam the grains",desc:"Pour the boiling water over the couscous with the butter, cover, and leave 10 min. Fluff with a fork and let it cool completely.",min:12},
   {name:"Mix",desc:"Stir the yogurt, condensed milk, vanilla, and nutmeg together until smooth, then fold in the cooled couscous and raisins.",min:3,timer:false},
   {name:"Chill",desc:"Chill at least 1 hour so the grains soften and it gets thick. Taste and add more condensed milk if you like it sweeter.",min:60}]},
 {id:"egusi-soup",title:"Egusi Soup with Spinach",cuisine:"Nigerian",diet:["halal"],serves:6,cost:3.00,meal:["dinner"],tags:["stew"],
  desc:"A rich, nutty Nigerian stew made with ground melon seeds (egusi) that cook into soft curds, simmered with beef, palm oil, peppers, and leafy greens. Eaten by pinching off pieces of fufu, pounded yam, or eba to scoop it up.",
  pantry:["egusi","beef","palm oil","onion","red bell pepper","scotch bonnet","spinach","bouillon","crayfish"],
  ingredients:["680 g (1½ lb) beef stew meat, cubed (halal-certified to keep it halal)","1 onion, half chopped, half blended","1½ tsp salt","2 bouillon cubes","1 cup (130 g) ground egusi (melon seeds), in African or international stores","⅓ cup (80 ml) red palm oil (or vegetable oil + 1 tsp paprika)","1 red bell pepper and 1 Scotch bonnet, blended with 2 tomatoes","2 tbsp ground crayfish (optional)","5 cups spinach or bitter leaf, chopped","Fufu, pounded yam, or rice, to serve"],
  steps:[
   {name:"Cook the beef",desc:"Put the beef in a pot with the chopped onion, salt, bouillon, and 3 cups water. Simmer until tender, 40 min. Keep the broth.",min:40},
   {name:"Make the egusi paste",desc:"Mix the ground egusi with the blended onion and a splash of water into a thick paste.",min:3,timer:false},
   {name:"Fry the egusi",desc:"Heat the palm oil in a large pot over medium heat for 1 min. Add the blended pepper mixture and fry 8 min. Drop in spoonfuls of egusi paste and let them cook undisturbed 5 min so they form curds, then gently stir.",min:14},
   {name:"Simmer",desc:"Add the beef, its broth, and the crayfish. Simmer 15 min, stirring now and then so the bottom doesn't burn, until thick and oil rises to the top.",min:15},
   {name:"Add the greens",desc:"Stir in the spinach and cook 3 min. Taste for salt. Serve with fufu, pounded yam, or rice.",min:3,timer:false}]},
 {id:"suya",title:"Suya (Spicy Peanut Beef Skewers)",cuisine:"Nigerian",diet:["halal"],serves:4,cost:3.00,meal:["dinner","snack"],tags:["grill"],
  desc:"Nigeria's favorite night-market street food: thin slices of beef coated in yaji, a smoky, spicy ground peanut and chile spice mix, grilled over fire until charred, then served with sliced onion, tomato, and more spice.",
  pantry:["beef sirloin","peanuts","cayenne","paprika","ginger","garlic powder","onion powder","bouillon","onion","tomato"],
  ingredients:["680 g (1½ lb) beef sirloin or flank, very thinly sliced (freeze 30 min first to make slicing easier; halal-certified to keep it halal)","Yaji spice: ½ cup roasted peanuts ground fine (or 3 tbsp peanut butter powder), 1–2 tsp cayenne, 2 tsp smoked paprika, 1 tsp ground ginger, 1 tsp garlic powder, 1 tsp onion powder, 1 bouillon cube crushed, 1 tsp salt","3 tbsp oil","Skewers (soak wooden ones)","Sliced red onion, tomato, and cabbage, to serve"],
  steps:[
   {name:"Make the yaji",desc:"Mix all the yaji ingredients. Save 3 tbsp for serving.",min:4,timer:false},
   {name:"Coat the beef",desc:"Toss the beef slices with the oil, then with the yaji until well coated. Thread onto skewers in a wavy, folded way. Marinate 30 min if you have time.",min:12,timer:false},
   {name:"Grill",desc:"Grill over high heat or under the broiler, 3–4 min per side, until charred at the edges.",min:8},
   {name:"Serve",desc:"Sprinkle with the extra yaji and serve with sliced onion, tomato, and cabbage.",min:2,timer:false}]},
 {id:"puff-puff",title:"Puff-Puff",cuisine:"Nigerian",diet:["vegan","vegetarian","halal"],serves:8,cost:0.30,meal:["snack","dessert"],tags:["fried","sweets"],
  desc:"Soft, fluffy, lightly sweet fried dough balls, golden outside and airy inside, sold by street vendors and served at every Nigerian party. Like a doughnut hole, but chewier.",
  pantry:["flour","sugar","yeast","nutmeg","oil"],
  ingredients:["3 cups (375 g) all-purpose flour","½ cup (100 g) sugar","2¼ tsp (1 packet) instant yeast","½ tsp salt","¼ tsp ground nutmeg","1½ cups (360 ml) warm water","Oil, for frying","Powdered sugar, to dust (optional)"],
  steps:[
   {name:"Mix the batter",desc:"Whisk the flour, sugar, yeast, salt, and nutmeg. Add the warm water and beat with a spoon or your hand 3 min into a thick, sticky, stretchy batter.",min:5,timer:false},
   {name:"Let it rise",desc:"Cover and leave in a warm place until doubled and full of bubbles, about 1 hour.",min:60},
   {name:"Fry",desc:"Heat 5 cm (2 in) of oil to 340°F (170°C). No thermometer? A drop of batter should sink slightly, then rise and bubble steadily within a few seconds. Scoop the batter with your hand and squeeze a ball out between your thumb and finger (or drop it from a spoon) into the oil. Fry, turning, until golden all over, 3–4 min. Drain on paper towels.",min:20,timer:false},
   {name:"Serve",desc:"Dust with powdered sugar if you like and eat warm.",min:1,timer:false}]},
 {id:"nigerian-stew",title:"Big-Pot Nigerian Red Stew",cuisine:"Nigerian",diet:["halal"],serves:8,cost:2.25,meal:["dinner"],tags:["stew","onepot"],
  desc:"The stew at the center of Nigerian home cooking: a deep red sauce of blended tomatoes, red peppers, Scotch bonnet, and onion, fried down in oil until rich and sweet, with chicken or beef. Made in a big pot each week and served with rice, yam, beans, or plantains.",
  pantry:["chicken","tomatoes","red bell pepper","scotch bonnet","onion","tomato paste","curry powder","thyme","bouillon"],
  ingredients:["1.4 kg (3 lb) chicken pieces or beef (halal-certified to keep it halal)","1 onion, half sliced, half for blending","1 tsp curry powder","1 tsp dried thyme","2 bouillon cubes","1½ tsp salt","Blend: 6 tomatoes (or 1 can / 800 g plum tomatoes), 3 red bell peppers, 1–2 Scotch bonnets, ½ onion","½ cup (120 ml) vegetable oil","3 tbsp tomato paste","2 bay leaves"],
  byo:{intro:"Every family has its stew. Keep the fried-down pepper and tomato base and change the protein and extras.",ideas:[
   ["Proteins","Chicken, beef, goat, turkey wings, fried fish, or boiled eggs added at the end."],
   ["Serve it with","White rice, boiled yam, fried plantain (dodo), beans, spaghetti, or bread."],
   ["Techniques","Boil the blended peppers first to cook off water, so the stew fries instead of steams. Fry the meat after boiling it for extra flavor. Freeze the stew base in portions."]]},
  steps:[
   {name:"Boil the meat",desc:"Put the meat in a pot with the sliced onion, curry, thyme, bouillon, salt, and 2 cups water. Simmer 25 min (beef: 45 min). Keep the broth.",min:25},
   {name:"Reduce the pepper blend",desc:"Blend the tomatoes, peppers, and onion until smooth. Boil the blend in a separate pot, stirring now and then, until thick and reduced by about a third, 20 min.",min:20},
   {name:"Fry the meat",desc:"Heat the oil in a large pot and fry the boiled meat until browned all over, 8 min. Set aside.",min:8},
   {name:"Fry the stew",desc:"In the same oil, fry the tomato paste 2 min, then add the reduced pepper blend and bay leaves. Fry, stirring often, until the oil floats to the top and it no longer tastes sour, 20 min.",min:22},
   {name:"Simmer together",desc:"Add the meat and 1 cup of the broth. Simmer 10 min, taste for salt, and serve.",min:10}]},
 {id:"harira",title:"Harira (Moroccan Tomato, Lentil, and Chickpea Soup)",cuisine:"Moroccan",diet:["halal"],serves:8,cost:1.50,meal:["dinner"],tags:["soup","beans","onepot"],
  desc:"The soup that breaks the fast every evening of Ramadan in Morocco: a thick, warmly spiced tomato soup with lentils, chickpeas, a little lamb or beef, fresh herbs, and a squeeze of lemon, served with dates.",
  pantry:["lentils","chickpeas","tomatoes","onion","celery","cilantro","parsley","ginger","cinnamon","turmeric","lamb","lemon","flour"],
  ingredients:["2 tbsp oil","225 g (½ lb) lamb or beef, in small cubes (halal-certified; or skip for vegetarian)","1 onion, diced","2 celery stalks, diced","1 handful each cilantro and parsley, chopped","1 tsp ground ginger","1 tsp ground turmeric","1 tsp ground cinnamon","1 tsp pepper","2 tsp salt","1 can (800 g / 28 oz) crushed tomatoes","3 tbsp tomato paste","¾ cup (150 g) brown lentils, rinsed","10 cups (2.4 L) water","1 can (400 g / 15 oz) chickpeas, drained","⅓ cup (40 g) flour whisked into 1 cup cold water","Lemon wedges and dates, to serve"],
  steps:[
   {name:"Brown and season",desc:"Heat the oil in a large pot over medium heat. Brown the meat 5 min. Add the onion, celery, half the herbs, and all the spices and cook 5 min.",min:10},
   {name:"Simmer",desc:"Add the tomatoes, tomato paste, lentils, water, and salt. Bring to a boil, then simmer 40 min until the lentils are soft.",min:40},
   {name:"Add chickpeas",desc:"Add the chickpeas and simmer 10 min.",min:10},
   {name:"Thicken",desc:"Stir the flour water again and pour it in slowly while stirring. Simmer, stirring often, until the soup turns thick and silky, 10 min. Add the rest of the herbs.",min:10},
   {name:"Serve",desc:"Taste for salt. Serve with lemon wedges and dates.",min:1,timer:false}]},
 {id:"couscous-seven-veg",title:"Couscous with Seven Vegetables",cuisine:"Moroccan",diet:["vegan","vegetarian","halal"],serves:6,cost:1.75,meal:["dinner"],tags:["stew","onepot"],
  desc:"The Friday family meal in Morocco: a big mound of fluffy couscous topped with a colorful stew of seven vegetables and chickpeas in a fragrant, saffron-tinted broth, with sweet caramelized onions and raisins. Families use whatever vegetables are in season.",
  pantry:["couscous","chickpeas","onion","carrots","turnip","zucchini","squash","cabbage","tomato","ginger","turmeric","cinnamon","raisins"],
  ingredients:["3 tbsp olive oil","1 onion, chopped","2 tomatoes, chopped","1 tsp each ground ginger, turmeric, and pepper","½ tsp cinnamon","Pinch of saffron (optional)","2 tsp salt","8 cups (2 L) water or vegetable broth","2 carrots, halved lengthwise","1 turnip, quartered","¼ cabbage, in a wedge","300 g (10 oz) butternut squash or pumpkin, in large chunks","2 zucchini, halved","1 can (400 g / 15 oz) chickpeas, drained","1 handful cilantro and parsley, tied in a bundle","2 cups (360 g) couscous","2 tbsp olive oil, for the couscous","Topping (tfaya): 2 onions sliced, ¼ cup raisins, 1 tbsp sugar, ½ tsp cinnamon, 2 tbsp oil"],
  byo:{intro:"\"Seven\" is a tradition, not a rule. Use 5–7 vegetables you have, added from hardest to softest.",ideas:[
   ["Hard (add first)","Carrots, turnips, sweet potato, cabbage."],
   ["Soft (add last)","Zucchini, squash, eggplant, green beans, fresh fava beans."],
   ["Proteins","Lamb shoulder or chicken pieces simmered in the broth before the vegetables (not vegan)."],
   ["Techniques","Spoon plenty of broth over the couscous so it soaks it up. Serve harissa on the side for heat."]]},
  steps:[
   {name:"Start the broth",desc:"Heat the olive oil in a large pot. Cook the onion 5 min, then add the tomatoes, spices, salt, and water. Bring to a boil.",min:8},
   {name:"Add the hard vegetables",desc:"Add the carrots, turnip, cabbage, and herb bundle. Simmer 20 min.",min:20},
   {name:"Add the soft vegetables",desc:"Add the squash, zucchini, and chickpeas and simmer 15 min until everything is tender. Meanwhile, cook the tfaya: fry the sliced onions in oil over medium-low heat 15 min until soft and golden, then add the raisins, sugar, and cinnamon for 3 min.",min:18},
   {name:"Make the couscous",desc:"Put the couscous in a bowl with the olive oil and a pinch of salt. Pour 2½ cups of the hot broth over, cover, and leave 8 min. Fluff with a fork.",min:9},
   {name:"Serve",desc:"Mound the couscous on a big platter, make a well, and arrange the vegetables on top. Spoon the tfaya over and serve extra broth in a bowl.",min:4,timer:false}]},
 {id:"kefta-tagine",title:"Kefta Tagine with Eggs",cuisine:"Moroccan",diet:["halal"],serves:4,cost:2.25,meal:["dinner"],tags:["stew","eggs","onepot"],
  desc:"Small spiced beef meatballs simmered in a cumin and paprika tomato sauce, with eggs cracked in at the end to poach. A fast, everyday Moroccan home dinner, eaten straight from the pot with bread.",
  pantry:["ground beef","onion","parsley","cilantro","cumin","paprika","cinnamon","crushed tomatoes","garlic","eggs","bread"],
  ingredients:["450 g (1 lb) ground beef or lamb (halal-certified to keep it halal)","½ onion, grated","1 handful each parsley and cilantro, chopped, divided","2 tsp ground cumin, divided","2 tsp paprika, divided","¼ tsp cinnamon","1½ tsp salt, divided","3 tbsp olive oil","3 garlic cloves, minced","1 can (800 g / 28 oz) crushed tomatoes","½ tsp chili flakes","4 eggs","Crusty bread, to serve"],
  steps:[
   {name:"Make the kefta",desc:"Mix the meat, onion, half the herbs, 1 tsp cumin, 1 tsp paprika, the cinnamon, and 1 tsp salt. Roll into small balls, about 2.5 cm (1 in).",min:12,timer:false},
   {name:"Make the sauce",desc:"Heat the oil in a wide pan with a lid over medium heat. Cook the garlic 1 min, then add the tomatoes, the rest of the cumin and paprika, chili, and ½ tsp salt. Simmer 10 min.",min:11},
   {name:"Simmer the kefta",desc:"Add the meatballs, cover, and simmer 15 min, turning once, until no longer pink in the middle (cut one to check).",min:15},
   {name:"Add the eggs",desc:"Make 4 wells in the sauce and crack an egg into each. Cover and cook until the whites are set and the yolks still soft, 6–8 min.",min:7},
   {name:"Serve",desc:"Scatter the rest of the herbs on top and bring the pan to the table with bread.",min:1,timer:false}]},
 {id:"zaalouk",title:"Zaalouk (Smoky Eggplant and Tomato Salad)",cuisine:"Moroccan",diet:["vegan","vegetarian","halal"],serves:4,cost:1.25,meal:["side","snack"],tags:["dip","salad"],
  desc:"A Moroccan cooked salad and dip: eggplant and tomatoes stewed down with garlic, cumin, and paprika until soft and spreadable, finished with olive oil, cilantro, and lemon. Eaten with bread, warm or cold.",
  pantry:["eggplant","tomatoes","garlic","cumin","paprika","olive oil","cilantro","lemon"],
  ingredients:["2 medium eggplants","4 ripe tomatoes, chopped (or 1 can diced)","4 tbsp olive oil, divided","4 garlic cloves, minced","1½ tsp ground cumin","1½ tsp paprika","Pinch of cayenne","1 tsp salt","1 handful cilantro, chopped","1 tbsp lemon juice","Bread, to serve"],
  steps:[
   {name:"Roast the eggplant",desc:"Prick the eggplants and broil them close to the heat, turning, until the skin is charred all over and they collapse, 20 min (or roast directly over a gas flame). Cool, then scoop out the flesh and chop.",min:22},
   {name:"Cook the tomatoes",desc:"Heat 2 tbsp olive oil in a skillet over medium heat. Cook the garlic 1 min, then add the tomatoes, spices, and salt and cook 8 min until saucy.",min:9},
   {name:"Simmer together",desc:"Add the eggplant and mash it into the tomatoes with a spoon. Cook, stirring, until thick and most liquid is gone, 10 min.",min:10},
   {name:"Finish",desc:"Stir in the cilantro, lemon, and remaining olive oil. Serve warm or at room temperature with bread.",min:2,timer:false}]},
 {id:"doro-wat",title:"Doro Wat (Ethiopian Spicy Chicken Stew)",cuisine:"Ethiopian",diet:["halal"],serves:6,cost:2.50,meal:["dinner"],tags:["stew"],
  desc:"Ethiopia's celebration stew: chicken and hard-boiled eggs slowly simmered in a deep red sauce of onions cooked down for nearly an hour with spiced butter and berbere, a complex chile spice blend. Rich, spicy, and served on injera bread for holidays.",
  pantry:["chicken","onions","berbere","butter","garlic","ginger","eggs","lemon"],
  ingredients:["1.4 kg (3 lb) bone-in chicken thighs and drumsticks, skin removed (halal-certified to keep it halal)","Juice of 1 lemon","1½ tsp salt, divided","4 large red onions, very finely chopped","½ cup (113 g) butter (or niter kibbeh, Ethiopian spiced butter)","3 tbsp berbere spice blend (in spice shops or online)","4 garlic cloves, minced","1 tbsp grated ginger","1½ cups (360 ml) water or chicken broth","6 hard-boiled eggs, peeled","Injera or rice, to serve"],
  steps:[
   {name:"Prep the chicken",desc:"Rub the chicken with the lemon juice and ½ tsp salt and set aside while you cook the onions.",min:3,timer:false},
   {name:"Cook the onions down",desc:"Put the onions in a dry heavy pot over medium heat and cook, stirring often, until they lose their water and start to turn golden, 15 min. Add the butter and cook 20 min more, stirring, until very soft and jammy.",min:35},
   {name:"Add the spices",desc:"Stir in the berbere, garlic, and ginger and cook 5 min, stirring, until dark red and fragrant. Add a splash of water if it starts to stick.",min:5},
   {name:"Simmer the chicken",desc:"Add the chicken, water, and 1 tsp salt. Cover and simmer, stirring now and then, until the chicken is very tender and the sauce is thick, 45 min.",min:45},
   {name:"Add the eggs",desc:"Lightly score the eggs all over with a knife so the sauce soaks in. Add them to the stew and simmer 10 min. Serve on injera or with rice.",min:10}]},
 {id:"shiro",title:"Shiro (Ethiopian Chickpea Stew)",cuisine:"Ethiopian",diet:["vegan","vegetarian","halal"],serves:4,cost:0.75,meal:["dinner"],tags:["stew","beans"],
  desc:"Ethiopia's everyday comfort food, eaten especially on fasting days: a smooth, creamy stew made from spiced chickpea flour simmered with onions, garlic, tomato, and berbere. Cheap, quick, and very satisfying with injera or bread.",
  pantry:["chickpea flour","onion","garlic","tomato","berbere","oil"],
  ingredients:["3 tbsp oil","1 red onion, very finely chopped","3 garlic cloves, minced","1 tomato, finely chopped","1–2 tsp berbere (or 1 tsp paprika + ½ tsp cayenne)","½ cup (60 g) chickpea flour (or shiro powder)","3 cups (720 ml) water","¾ tsp salt","1 jalapeño, sliced, to serve","Injera or bread, to serve"],
  steps:[
   {name:"Cook the onion",desc:"Cook the onion in a dry pot over medium heat 5 min until it softens and dries. Add the oil, garlic, tomato, and berbere and cook 5 min until saucy.",min:10},
   {name:"Whisk in the flour",desc:"Whisk the chickpea flour into 1 cup of the water until smooth, then whisk it into the pot along with the rest of the water and the salt.",min:3,timer:false},
   {name:"Simmer",desc:"Simmer on low, whisking often, until thick, creamy, and the raw flour taste is gone, 15 min. Add water if it gets too thick; it should be like thick gravy.",min:15},
   {name:"Serve",desc:"Top with sliced jalapeño and serve with injera or bread.",min:1,timer:false}]},
 {id:"atakilt-wat",title:"Atakilt Wat (Cabbage, Carrot, and Potato)",cuisine:"Ethiopian",diet:["vegan","vegetarian","halal"],serves:6,cost:0.75,meal:["dinner","side"],tags:["stew","onepot"],
  desc:"A mild, golden Ethiopian vegetable stew of cabbage, carrots, and potatoes slowly cooked with turmeric, ginger, and garlic until tender and sweet. Part of every Ethiopian vegetarian platter.",
  pantry:["cabbage","carrots","potatoes","onion","garlic","ginger","turmeric","cumin"],
  ingredients:["¼ cup (60 ml) olive oil","1 onion, thinly sliced","3 carrots, sliced","4 garlic cloves, minced","1 tbsp grated ginger","1 tsp ground turmeric","½ tsp ground cumin","1½ tsp salt","½ head green cabbage, chopped","3 potatoes, cut into 3 cm (1 in) chunks","1 cup (240 ml) water","1 jalapeño, sliced (optional)","Injera, rice, or bread, to serve"],
  steps:[
   {name:"Soften the onion and carrots",desc:"Heat the oil in a large pot over medium heat. Cook the onion and carrots 8 min until soft.",min:8},
   {name:"Add the spices",desc:"Stir in the garlic, ginger, turmeric, cumin, and salt for 1 min.",min:1,timer:false},
   {name:"Add cabbage and potatoes",desc:"Add the cabbage, potatoes, jalapeño, and water. Stir, cover, and cook on medium-low, stirring every 5 min, until the potatoes are tender and the cabbage is soft and sweet, 25 min.",min:25},
   {name:"Serve",desc:"Taste for salt and serve warm with injera, rice, or bread.",min:1,timer:false}]},
 {id:"beef-tibs",title:"Beef Tibs",cuisine:"Ethiopian",diet:["halal"],serves:4,cost:3.50,meal:["dinner"],tags:["stirfry"],
  desc:"A popular Ethiopian dish of beef cubes quickly sautéed with onions, peppers, garlic, rosemary, and spiced butter until browned outside and juicy inside. Served sizzling, often for guests, with injera or bread.",
  pantry:["beef sirloin","onion","jalapeño","garlic","rosemary","butter","berbere","tomato"],
  ingredients:["680 g (1½ lb) beef sirloin, in 2 cm (¾ in) cubes (halal-certified to keep it halal)","1 tsp salt","2 tbsp oil","1 red onion, sliced","2 jalapeños, sliced","1 tomato, diced","3 garlic cloves, minced","2 sprigs rosemary","3 tbsp butter (or niter kibbeh)","1 tsp berbere (optional, for spicy tibs)","Injera or bread, to serve"],
  steps:[
   {name:"Sear the beef",desc:"Pat the beef dry and season with the salt. Heat the oil in a large skillet over high heat. Sear the beef in one layer, without moving, 2 min, then stir and cook 2 min more. Move it to a plate.",min:5},
   {name:"Cook the vegetables",desc:"Lower to medium-high. Cook the onion and jalapeño 4 min, then add the tomato, garlic, and rosemary for 2 min.",min:6},
   {name:"Finish with butter",desc:"Return the beef, add the butter and berbere, and toss 2 min until glossy and the beef is cooked to your liking.",min:2,timer:false},
   {name:"Serve",desc:"Serve sizzling hot with injera or bread.",min:1,timer:false}]},
 {id:"lablabi",title:"Lablabi (Tunisian Chickpea Soup)",cuisine:"North African",diet:["vegan","vegetarian","halal"],serves:4,cost:0.75,meal:["breakfast","dinner"],tags:["soup","beans"],
  desc:"A cheap, warming Tunisian street breakfast: chickpeas in a garlicky cumin broth poured over torn stale bread, then finished at the table with harissa, olive oil, lemon, capers, and often a soft egg.",
  pantry:["chickpeas","garlic","cumin","harissa","olive oil","lemon","bread"],
  ingredients:["2 cans (400 g / 15 oz each) chickpeas, with their liquid","4 cups (1 L) water or vegetable broth","5 garlic cloves, crushed","2 tsp ground cumin","1 tsp salt","1–2 tbsp harissa paste","4 thick slices stale crusty bread, torn","To serve: olive oil, lemon wedges, capers, more cumin; a soft-boiled egg (not vegan)"],
  steps:[
   {name:"Simmer",desc:"Put the chickpeas with their liquid, water, garlic, cumin, and salt in a pot. Simmer 20 min until the garlic is soft and the broth is flavorful. Stir in the harissa.",min:20},
   {name:"Build the bowls",desc:"Put torn bread in the bottom of each bowl and ladle the hot chickpeas and broth over it.",min:2,timer:false},
   {name:"Finish at the table",desc:"Everyone adds a generous drizzle of olive oil, lemon, capers, cumin, more harissa, and an egg if they like, then stirs it all together.",min:2,timer:false}]},
 {id:"chorba-frik",title:"Chorba Frik (Algerian Lamb and Freekeh Soup)",cuisine:"North African",diet:["halal"],serves:6,cost:2.50,meal:["dinner"],tags:["soup","onepot"],
  desc:"A hearty Algerian soup, especially loved during Ramadan: lamb, chickpeas, and cracked green wheat (freekeh) simmered in a tomato broth spiced with cinnamon, paprika, and mint. Thick, smoky from the freekeh, and filling.",
  pantry:["lamb","freekeh","chickpeas","onion","tomato paste","cinnamon","paprika","cilantro","mint"],
  ingredients:["2 tbsp olive oil","450 g (1 lb) lamb shoulder or beef, in small cubes (halal-certified to keep it halal)","1 onion, finely diced","1 tsp paprika","1 tsp ground cinnamon","½ tsp black pepper","1½ tsp salt","3 tbsp tomato paste","8 cups (2 L) water","1 can (400 g / 15 oz) chickpeas, drained","¾ cup (130 g) cracked freekeh (or bulgur)","1 handful cilantro, chopped","1 tsp dried mint","Lemon wedges, to serve"],
  steps:[
   {name:"Brown the meat",desc:"Heat the oil in a large pot over medium-high heat. Brown the meat with the onion, 8 min.",min:8},
   {name:"Add the spices",desc:"Stir in the paprika, cinnamon, pepper, salt, and tomato paste for 2 min.",min:2,timer:false},
   {name:"Simmer the meat",desc:"Add the water, bring to a boil, and simmer covered 40 min, until the meat is nearly tender.",min:40},
   {name:"Add freekeh and chickpeas",desc:"Stir in the freekeh, chickpeas, and half the cilantro. Simmer, stirring often, until the freekeh is tender and the soup is thick, 25 min.",min:25},
   {name:"Serve",desc:"Stir in the dried mint and the rest of the cilantro. Taste for salt and serve with lemon.",min:1,timer:false}]}
);
